import hashlib,struct,json,sys,unicodedata
out=bytearray();count=0;exp=[]
for a in range(128,256):
 for b in range(256):
  try: points=list(map(ord,bytes([a,b]).decode('big5hkscs')))
  except UnicodeDecodeError: points=[]
  if points: count+=1
  if len(points)>1: exp.append([a*256+b,points])
  out.extend(struct.pack('<ii',*(points+[-1,-1])[:2]))
result={'version':sys.version,'unicode':unicodedata.unidata_version,'decodeCount':count,'decodeSha256':hashlib.sha256(out).hexdigest(),'expansions':exp}
out=bytearray();count=0
for p in range(0x110000):
 try: value=int.from_bytes(chr(p).encode('big5hkscs'),'big');count+=1
 except UnicodeEncodeError: value=-1
 out.extend(struct.pack('<i',value))
result.update(encodeCount=count,encodeSha256=hashlib.sha256(out).hexdigest())
